data.script:
function check(value,label){if(!value)throw new Error(label);}
const source=Action.find('QA Native catalog readonly'), group=ActionGroup.find('Native catalog QA'), separator=Action.find('QA Native catalog section');
check(source && source.uuid==='BBBF0003-0000-4000-8000-000000000007','source identity');
check(source.name==='QA Native catalog readonly' && source.isSeparator===false,'source values');
check(separator && separator.isSeparator===true,'separator value');
check(group && group.name==='Native catalog QA' && /^[0-9a-f-]{36}$/i.test(group.uuid),'group identity');
for(const value of [action,source,separator]){for(const key of ['name','uuid','isSeparator','configuredValues']){const before=value[key];check(Reflect.set(value,key,'wrong')===false,'readonly '+key);check(value[key]===before,'retained '+key);}}
for(const key of ['name','uuid']){const before=group[key];check(Reflect.set(group,key,'wrong')===false,'readonly group '+key);check(group[key]===before,'retained group '+key);}
check(Action.find('QA missing catalog action')===undefined && ActionGroup.find('QA missing catalog group')===undefined,'missing lookups');
check(group.actions.some(value=>value.uuid===source.uuid) && group.actions.some(value=>value.uuid===separator.uuid),'group membership');
check(ActionGroup.getAll().some(value=>value.uuid===group.uuid),'getAll identity');
editor.setText('Catalog readonly passed café 🐼');draft.update();
